package main
import("bufio";"bytes";"fmt";"io";"net";"strings";"sync";"time";f "github.com/secsy/goftp")
func main(){ln,e:=net.Listen("tcp","127.0.0.1:0");if e!=nil{panic(e)};defer ln.Close();var mu sync.Mutex;var leaked net.Conn;done:=make(chan struct{});go func(){defer close(done);c,e:=ln.Accept();if e!=nil{return};defer c.Close();fmt.Fprint(c,"220 ready\r\n");sc:=bufio.NewScanner(c);var data net.Conn;for sc.Scan(){line:=sc.Text();op:=strings.SplitN(line," ",2)[0];switch op{case "USER":fmt.Fprint(c,"230 ok\r\n");case "FEAT":fmt.Fprint(c,"211-Features\r\n UTF8\r\n211 End\r\n");case "TYPE":fmt.Fprint(c,"200 type\r\n");case "EPSV":dl,e:=net.Listen("tcp","127.0.0.1:0");if e!=nil{panic(e)};fmt.Fprintf(c,"229 passive (|||%d|)\r\n",dl.Addr().(*net.TCPAddr).Port);data,e=dl.Accept();dl.Close();if e!=nil{return};case "RETR":if strings.HasSuffix(line,"/denied"){mu.Lock();leaked=data;mu.Unlock();fmt.Fprint(c,"550 refused\r\n")}else{fmt.Fprint(c,"150 start\r\n");fmt.Fprint(data,"ok");data.Close();fmt.Fprint(c,"226 done\r\n")};case "QUIT":fmt.Fprint(c,"221 bye\r\n");return;default:fmt.Fprint(c,"200 ok\r\n")}}}();c,e:=f.DialConfig(f.Config{User:"anonymous",Timeout:time.Second,ConnectionsPerHost:1},ln.Addr().String());if e!=nil{panic(e)};defer c.Close();var b bytes.Buffer;e=c.Retrieve("/denied",&b);fe,ok:=e.(f.Error);if !ok||fe.Code()!=550{panic(fmt.Sprint("expected 550: ",e))};mu.Lock();dc:=leaked;mu.Unlock();if dc==nil{panic("missing data connection")};dc.SetReadDeadline(time.Now().Add(60*time.Millisecond));var one [1]byte;_,e=dc.Read(one[:]);ne,timeout:=e.(net.Error);unclosed:=timeout&&ne.Timeout();dc.Close();if !unclosed{panic(fmt.Sprint("baseline no longer leaks: ",e))};b.Reset();if e=c.Retrieve("/ok",&b);e!=nil{panic(e)};if b.String()!="ok"{panic("normal data differs")};fmt.Printf("denied_code=550 passive_unclosed=%v normal=%s\n",unclosed,b.String());c.Close();select{case <-done:case <-time.After(time.Second):panic("control server stuck")};_ = io.EOF}
